"""Sortie ZF4, batch 7: the Ramanujan block (LargeSieve
norm_gaussSum_one_squarefree: the trivial character's Gauss sum at
squarefree level has modulus 1) and the induced-character Gauss sum
(norm_sq_gaussSum_changeLevel)."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
from zf4lib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

UV = '( U x. V )'
def TO(n): return GS(n, ONE(n))
def PH(t): return '( ( mmu ` %s ) =/= 0 -> ( abs ` %s ) = 1 )' % (t, TO(t))
def BEZ(a, b, u='U', v='V'): return '( %s e. ZZ /\\ %s e. ZZ /\\ ( ( %s x. %s ) + ( %s x. %s ) ) = 1 )' % (a, b, a, v, b, u)
def grpone(w, ante, nst, n):
    """( ante -> ( DChr ` n ) e. Grp ), ( ante -> 1n e. Dn )"""
    g = w.s([], 'eqid', '( DChr ` %s ) = ( DChr ` %s )' % (n, n)); d = w.s([], 'eqid', '%s = %s' % (DB(n), DB(n))); o = w.s([], 'eqid', '%s = %s' % (ONE(n), ONE(n)))
    grp = w.s([w.s([nst, w.s([g], 'dchrabl', '( %s e. NN -> ( DChr ` %s ) e. Abel )' % (n, n))], 'syl', '( %s -> ( DChr ` %s ) e. Abel )' % (ante, n))], 'ablgrpd', '( %s -> ( DChr ` %s ) e. Grp )' % (ante, n))
    one = w.s([grp, w.s([d, o], 'grpidcl', '( ( DChr ` %s ) e. Grp -> %s e. %s )' % (n, ONE(n), DB(n)))], 'syl', '( %s -> %s e. %s )' % (ante, ONE(n), DB(n)))
    return grp, one

# ---- bezex: a Bezout pair in the form the CRT lemmas take
A0 = '( U e. NN /\\ V e. NN /\\ ( U gcd V ) = 1 )'
P = '( U gcd V ) = ( ( U x. s ) + ( V x. t ) )'; QQ = BEZ('t', 's')
w = W('bezex', 'Coprime U, V have a Bezout pair t V + s U = 1 (set.mm bezout in the form the CRT lemmas take).')
u = w.s([], 'simp1', '( %s -> U e. NN )' % A0); v = w.s([], 'simp2', '( %s -> V e. NN )' % A0); cop = w.s([], 'simp3', '( %s -> ( U gcd V ) = 1 )' % A0)
ex = w.s([w.s([u], 'nnzd', '( %s -> U e. ZZ )' % A0), w.s([v], 'nnzd', '( %s -> V e. ZZ )' % A0), w.inst('bezout')], 'syl2anc', '( %s -> E. s e. ZZ E. t e. ZZ %s )' % (A0, P))
As = '( %s /\\ s e. ZZ )' % A0; Ast = '( %s /\\ t e. ZZ )' % As; A2 = '( %s /\\ %s )' % (Ast, P)
s = w.s([w.s([], 'simplr', '( %s -> s e. ZZ )' % Ast)], 'adantr', '( %s -> s e. ZZ )' % A2); t = w.s([w.s([], 'simpr', '( %s -> t e. ZZ )' % Ast)], 'adantr', '( %s -> t e. ZZ )' % A2)
uc = w.s([w.s([u], 'ad3antrrr', '( %s -> U e. NN )' % A2)], 'nncnd', '( %s -> U e. CC )' % A2); vc = w.s([w.s([v], 'ad3antrrr', '( %s -> V e. NN )' % A2)], 'nncnd', '( %s -> V e. CC )' % A2)
sc = w.s([s], 'zcnd', '( %s -> s e. CC )' % A2); tc = w.s([t], 'zcnd', '( %s -> t e. CC )' % A2)
e1 = w.s([w.s([tc, vc], 'mulcomd', '( %s -> ( t x. V ) = ( V x. t ) )' % A2), w.s([sc, uc], 'mulcomd', '( %s -> ( s x. U ) = ( U x. s ) )' % A2)], 'oveq12d', '( %s -> ( ( t x. V ) + ( s x. U ) ) = ( ( V x. t ) + ( U x. s ) ) )' % A2)
e2 = w.s([w.s([vc, tc], 'mulcld', '( %s -> ( V x. t ) e. CC )' % A2), w.s([uc, sc], 'mulcld', '( %s -> ( U x. s ) e. CC )' % A2)], 'addcomd', '( %s -> ( ( V x. t ) + ( U x. s ) ) = ( ( U x. s ) + ( V x. t ) ) )' % A2)
e3 = w.s([w.s([w.s([], 'simpr', '( %s -> %s )' % (A2, P))], 'eqcomd', '( %s -> ( ( U x. s ) + ( V x. t ) ) = ( U gcd V ) )' % A2), w.s([cop], 'ad3antrrr', '( %s -> ( U gcd V ) = 1 )' % A2)], 'eqtrd', '( %s -> ( ( U x. s ) + ( V x. t ) ) = 1 )' % A2)
q = w.s([t, s, w.s([e1, e2, e3], '3eqtrd', '( %s -> ( ( t x. V ) + ( s x. U ) ) = 1 )' % A2)], '3jca', '( %s -> %s )' % (A2, QQ))
i1 = w.s([w.s([q], 'ex', '( %s -> ( %s -> %s ) )' % (Ast, P, QQ))], 'reximdva', '( %s -> ( E. t e. ZZ %s -> E. t e. ZZ %s ) )' % (As, P, QQ))
i2 = w.s([i1], 'reximdva', '( %s -> ( E. s e. ZZ E. t e. ZZ %s -> E. s e. ZZ E. t e. ZZ %s ) )' % (A0, P, QQ))
w.qed([ex, i2], 'mpd', '( %s -> E. s e. ZZ E. t e. ZZ %s )' % (A0, QQ)); run(w)

# ---- dchrgs1sqflem1: level 1
O1 = ONE('1'); R1 = R('1'); L1 = LZ('1'); TM = TERMR(O1, '1', 'a')
w = W('dchrgs1sqflem1', 'The Gauss sum of the trivial character mod 1 is 1 (Lean h1 in norm_gaussSum_one_squarefree).')
n1 = w.s([], '1nn', '1 e. NN')
grp, one = grpone(w, '1 e. NN', w.s([], 'id', '( 1 e. NN -> 1 e. NN )'), '1')
one0 = w.s([n1, one], 'ax-mp', '%s e. %s' % (O1, DB('1')))
v2 = w.s([w.s([n1, one0], 'pm3.2i', '( 1 e. NN /\\ %s e. %s )' % (O1, DB('1'))), w.inst('dchrgsval2')], 'ax-mp', '%s = sum_ a e. %s %s' % (TO('1'), FZO('1'), TM))
s0 = w.s([w.s([], 'fzo01', '%s = { 0 }' % FZO('1'))], 'sumeq1i', 'sum_ a e. %s %s = sum_ a e. { 0 } %s' % (FZO('1'), TM, TM))
# the term at 0
ia = w.s([], 'id', '( a = 0 -> a = 0 )'); cst, T0 = w.congr(TM, {'a': '0'}, 'a = 0', {'a': ia})
assert T0 == TERMR(O1, '1', '0'), T0
z = w.s([], 'eqid', '( Z/nZ ` 1 ) = ( Z/nZ ` 1 )'); zu = w.s([], 'eqid', '%s = %s' % (UZ('1'), UZ('1'))); l = w.s([], 'eqid', '%s = %s' % (L1, L1)); g = w.s([], 'eqid', '( DChr ` 1 ) = ( DChr ` 1 )'); o = w.s([], 'eqid', '%s = %s' % (O1, O1))
un = w.s([w.s([w.s([], '0z', '0 e. ZZ'), w.inst('gcd1')], 'ax-mp', '( 0 gcd 1 ) = 1'), w.s([w.s([w.s([], '1nn0', '1 e. NN0'), w.s([], '0z', '0 e. ZZ')], 'pm3.2i', '( 1 e. NN0 /\\ 0 e. ZZ )'), w.s([z, zu, l], 'znunit', '( ( 1 e. NN0 /\\ 0 e. ZZ ) -> ( ( %s ` 0 ) e. %s <-> ( 0 gcd 1 ) = 1 ) )' % (L1, UZ('1')))], 'ax-mp', '( ( %s ` 0 ) e. %s <-> ( 0 gcd 1 ) = 1 )' % (L1, UZ('1')))], 'mpbir', '( %s ` 0 ) e. %s' % (L1, UZ('1')))
A1 = '1 e. NN'
d1 = w.s([g, z, o, zu, w.s([], 'id', '( 1 e. NN -> 1 e. NN )'), w.s([un], 'a1i', '( %s -> ( %s ` 0 ) e. %s )' % (A1, L1, UZ('1')))], 'dchr1', '( %s -> ( %s ` ( %s ` 0 ) ) = 1 )' % (A1, O1, L1))
d1c = w.s([n1, d1], 'ax-mp', '( %s ` ( %s ` 0 ) ) = 1' % (O1, L1))
rc = w.s([w.s([n1, w.inst('root1cl')], 'ax-mp', '( %s e. CC /\\ %s =/= 0 )' % (R1, R1))], 'simpli', '%s e. CC' % R1)
r0 = w.s([rc, w.inst('exp0')], 'ax-mp', '( %s ^ 0 ) = 1' % R1)
t1 = w.s([w.s([d1c, r0], 'oveq12i', '%s = ( 1 x. 1 )' % T0), w.s([], '1t1e1', '( 1 x. 1 ) = 1')], 'eqtri', '%s = 1' % T0)
sub = w.s([cst, t1], 'eqtrdi', '( a = 0 -> %s = 1 )' % TM)
ss = w.s([w.s([w.s([], 'c0ex', '0 e. _V'), w.s([], 'ax-1cn', '1 e. CC')], 'pm3.2i', '( 0 e. _V /\\ 1 e. CC )'), w.s([sub], 'sumsn', '( ( 0 e. _V /\\ 1 e. CC ) -> sum_ a e. { 0 } %s = 1 )' % TM)], 'ax-mp', 'sum_ a e. { 0 } %s = 1' % TM)
w.qed([v2, s0, ss], '3eqtri', '%s = 1' % TO('1')); run(w)

# ---- dchrgs1prm: prime level (Mathlib gaussSum_one_left)
A0 = 'P e. Prime'; OP = ONE('P'); RP_ = R('P'); LP = LZ('P'); FP = FZO('P'); TM = TERMR(OP, 'P', 'a')
IF = 'if ( a e. { 0 } , 1 , 0 )'; SUB = '( %s - %s )' % (RP('a', 'P'), IF)
w = W('dchrgs1prm', 'The Gauss sum of the trivial character mod a prime P is -u 1 (Mathlib gaussSum_one_left; Lean hprime in norm_gaussSum_one_squarefree).')
p = w.s([], 'id', '( %s -> P e. Prime )' % A0); pn = w.s([p, w.inst('prmnn')], 'syl', '( %s -> P e. NN )' % A0); pz = w.s([pn], 'nnzd', '( %s -> P e. ZZ )' % A0)
grp, one = grpone(w, A0, pn, 'P')
hc = w.s([pn, one], 'jca', '( %s -> ( P e. NN /\\ %s e. %s ) )' % (A0, OP, DB('P')))
v2 = w.s([hc, w.inst('dchrgsval2')], 'syl', '( %s -> %s = sum_ a e. %s %s )' % (A0, TO('P'), FP, TM))
Aa = '( %s /\\ a e. %s )' % (A0, FP); A1 = '( %s /\\ a = 0 )' % Aa; A2 = '( %s /\\ -. a = 0 )' % Aa
am = w.s([], 'simpr', '( %s -> a e. %s )' % (Aa, FP)); az = w.s([am, w.inst('elfzoelz')], 'syl', '( %s -> a e. ZZ )' % Aa)
pna = w.s([pn], 'adantr', '( %s -> P e. NN )' % Aa); hca = w.s([hc], 'adantr', '( %s -> ( P e. NN /\\ %s e. %s ) )' % (Aa, OP, DB('P')))
rc = w.s([pna, az, w.inst('root1expcl')], 'syl2anc', '( %s -> %s e. CC )' % (Aa, RP('a', 'P')))
g, z, d, l = dchyp(w, 'P'); zu = w.s([], 'eqid', '%s = %s' % (UZ('P'), UZ('P'))); o = w.s([], 'eqid', '%s = %s' % (OP, OP))
# P =/= 1
pne1 = w.s([w.s([w.s([w.s([p, w.inst('prmuz2')], 'syl', '( %s -> P e. ( ZZ>= ` 2 ) )' % A0), w.inst('eluz2b2')], 'sylib', '( %s -> ( P e. NN /\\ 1 < P ) )' % A0)], 'simprd', '( %s -> 1 < P )' % A0)], 'gtned', '( %s -> P =/= 1 )' % A0)
w.lines.pop()
lt1 = w.s([w.s([w.s([p, w.inst('prmuz2')], 'syl', '( %s -> P e. ( ZZ>= ` 2 ) )' % A0), w.inst('eluz2b2')], 'sylib', '( %s -> ( P e. NN /\\ 1 < P ) )' % A0)], 'simprd', '( %s -> 1 < P )' % A0)
pne1 = w.s([w.s([], '1red', '( %s -> 1 e. RR )' % A0), lt1], 'gtned', '( %s -> P =/= 1 )' % A0)
# case a = 0: term = 0 = R^a - 1
a0 = w.s([], 'simpr', '( %s -> a = 0 )' % A1)
g0 = w.s([w.s([w.s([a0], 'oveq1d', '( %s -> ( a gcd P ) = ( 0 gcd P ) )' % A1), w.s([w.s([pz], 'ad2antrr', '( %s -> P e. ZZ )' % A1), w.inst('gcd0id')], 'syl', '( %s -> ( 0 gcd P ) = ( abs ` P ) )' % A1)], 'eqtrd', '( %s -> ( a gcd P ) = ( abs ` P ) )' % A1), w.s([w.s([w.s([pn], 'ad2antrr', '( %s -> P e. NN )' % A1)], 'nnred', '( %s -> P e. RR )' % A1), w.s([w.s([w.s([pn], 'ad2antrr', '( %s -> P e. NN )' % A1)], 'nnnn0d', '( %s -> P e. NN0 )' % A1)], 'nn0ge0d', '( %s -> 0 <_ P )' % A1), w.inst('absid')], 'syl2anc', '( %s -> ( abs ` P ) = P )' % A1)], 'eqtrd', '( %s -> ( a gcd P ) = P )' % A1)
ncop = w.s([w.s([w.s([pne1], 'ad2antrr', '( %s -> P =/= 1 )' % A1)], 'neneqd', '( %s -> -. P = 1 )' % A1), w.s([g0], 'eqeq1d', '( %s -> ( ( a gcd P ) = 1 <-> P = 1 ) )' % A1)], 'mtbird', '( %s -> -. ( a gcd P ) = 1 )' % A1)
x0 = w.s([w.s([hca], 'adantr', '( %s -> ( P e. NN /\\ %s e. %s ) )' % (A1, OP, DB('P'))), w.s([az], 'adantr', '( %s -> a e. ZZ )' % A1), ncop, w.inst('dchrzrh0')], 'syl3anc', '( %s -> %s = 0 )' % (A1, EV(OP, 'P', 'a')))
t0 = w.s([w.s([x0], 'oveq1d', '( %s -> %s = ( 0 x. %s ) )' % (A1, TM, RP('a', 'P'))), w.s([w.s([rc], 'adantr', '( %s -> %s e. CC )' % (A1, RP('a', 'P')))], 'mul02d', '( %s -> ( 0 x. %s ) = 0 )' % (A1, RP('a', 'P')))], 'eqtrd', '( %s -> %s = 0 )' % (A1, TM))
ra0 = w.s([w.s([a0], 'oveq2d', '( %s -> %s = ( %s ^ 0 ) )' % (A1, RP('a', 'P'), RP_)), w.s([w.s([w.s([w.s([pn], 'ad2antrr', '( %s -> P e. NN )' % A1), w.inst('root1cl')], 'syl', '( %s -> ( %s e. CC /\\ %s =/= 0 ) )' % (A1, RP_, RP_))], 'simpld', '( %s -> %s e. CC )' % (A1, RP_))], 'exp0d', '( %s -> ( %s ^ 0 ) = 1 )' % (A1, RP_))], 'eqtrd', '( %s -> %s = 1 )' % (A1, RP('a', 'P')))
if1 = w.s([w.s([a0, w.s([], 'velsn', '( a e. { 0 } <-> a = 0 )')], 'sylibr', '( %s -> a e. { 0 } )' % A1)], 'iftrued', '( %s -> %s = 1 )' % (A1, IF))
s0 = w.s([w.s([ra0, if1], 'oveq12d', '( %s -> %s = ( 1 - 1 ) )' % (A1, SUB)), w.s([w.s([], '1m1e0', '( 1 - 1 ) = 0')], 'a1i', '( %s -> ( 1 - 1 ) = 0 )' % A1)], 'eqtrd', '( %s -> %s = 0 )' % (A1, SUB))
c1 = w.s([t0, s0], 'eqtr4d', '( %s -> %s = %s )' % (A1, TM, SUB))
# case a =/= 0: term = R^a = R^a - 0
an0 = w.s([w.s([], 'simpr', '( %s -> -. a = 0 )' % A2)], 'neqned', '( %s -> a =/= 0 )' % A2)
ann = w.s([w.s([w.s([w.s([am], 'adantr', '( %s -> a e. %s )' % (A2, FP)), w.inst('elfzonn0')], 'syl', '( %s -> a e. NN0 )' % A2), an0], 'jca', '( %s -> ( a e. NN0 /\\ a =/= 0 ) )' % A2), w.inst('elnnne0')], 'sylibr', '( %s -> a e. NN )' % A2)
alt = w.s([w.s([am], 'adantr', '( %s -> a e. %s )' % (A2, FP)), w.inst('elfzolt2')], 'syl', '( %s -> a < P )' % A2)
nle = w.s([w.s([w.s([ann], 'nnred', '( %s -> a e. RR )' % A2), w.s([w.s([pn], 'ad2antrr', '( %s -> P e. NN )' % A2)], 'nnred', '( %s -> P e. RR )' % A2), w.inst('ltnle')], 'syl2anc', '( %s -> ( a < P <-> -. P <_ a ) )' % A2)], 'mpbid' if False else 'mpbid', '( %s -> -. P <_ a )' % A2)
w.lines.pop()
nle = w.s([alt, w.s([w.s([ann], 'nnred', '( %s -> a e. RR )' % A2), w.s([w.s([pn], 'ad2antrr', '( %s -> P e. NN )' % A2)], 'nnred', '( %s -> P e. RR )' % A2), w.inst('ltnle')], 'syl2anc', '( %s -> ( a < P <-> -. P <_ a ) )' % A2)], 'mpbid', '( %s -> -. P <_ a )' % A2)
ndv = w.s([nle, w.s([w.s([pz], 'ad2antrr', '( %s -> P e. ZZ )' % A2), ann, w.inst('dvdsle')], 'syl2anc', '( %s -> ( P || a -> P <_ a ) )' % A2)], 'mtod', '( %s -> -. P || a )' % A2)
cp = w.s([ndv, w.s([w.s([p], 'ad2antrr', '( %s -> P e. Prime )' % A2), w.s([az], 'adantr', '( %s -> a e. ZZ )' % A2), w.inst('coprm')], 'syl2anc', '( %s -> ( -. P || a <-> ( P gcd a ) = 1 ) )' % A2)], 'mpbid', '( %s -> ( P gcd a ) = 1 )' % A2)
cop = w.s([w.s([w.s([az], 'adantr', '( %s -> a e. ZZ )' % A2), w.s([pz], 'ad2antrr', '( %s -> P e. ZZ )' % A2)], 'gcdcomd', '( %s -> ( a gcd P ) = ( P gcd a ) )' % A2), cp], 'eqtrd', '( %s -> %s )' % (A2, COP('a', 'P')))
un = w.s([cop, w.s([w.s([w.s([pn], 'ad2antrr', '( %s -> P e. NN )' % A2)], 'nnnn0d', '( %s -> P e. NN0 )' % A2), w.s([az], 'adantr', '( %s -> a e. ZZ )' % A2), w.s([z, zu, l], 'znunit', '( ( P e. NN0 /\\ a e. ZZ ) -> ( ( %s ` a ) e. %s <-> %s ) )' % (LP, UZ('P'), COP('a', 'P')))], 'syl2anc', '( %s -> ( ( %s ` a ) e. %s <-> %s ) )' % (A2, LP, UZ('P'), COP('a', 'P')))], 'mpbird', '( %s -> ( %s ` a ) e. %s )' % (A2, LP, UZ('P')))
x1 = w.s([g, z, o, zu, w.s([pn], 'ad2antrr', '( %s -> P e. NN )' % A2), un], 'dchr1', '( %s -> %s = 1 )' % (A2, EV(OP, 'P', 'a')))
t1 = w.s([w.s([x1], 'oveq1d', '( %s -> %s = ( 1 x. %s ) )' % (A2, TM, RP('a', 'P'))), w.s([w.s([rc], 'adantr', '( %s -> %s e. CC )' % (A2, RP('a', 'P')))], 'mullidd', '( %s -> ( 1 x. %s ) = %s )' % (A2, RP('a', 'P'), RP('a', 'P')))], 'eqtrd', '( %s -> %s = %s )' % (A2, TM, RP('a', 'P')))
if0 = w.s([w.s([w.s([], 'simpr', '( %s -> -. a = 0 )' % A2), w.s([], 'velsn', '( a e. { 0 } <-> a = 0 )')], 'sylnibr', '( %s -> -. a e. { 0 } )' % A2)], 'iffalsed', '( %s -> %s = 0 )' % (A2, IF))
s1 = w.s([w.s([if0], 'oveq2d', '( %s -> %s = ( %s - 0 ) )' % (A2, SUB, RP('a', 'P'))), w.s([w.s([rc], 'adantr', '( %s -> %s e. CC )' % (A2, RP('a', 'P')))], 'subid1d', '( %s -> ( %s - 0 ) = %s )' % (A2, RP('a', 'P'), RP('a', 'P')))], 'eqtrd', '( %s -> %s = %s )' % (A2, SUB, RP('a', 'P')))
c2 = w.s([t1, s1], 'eqtr4d', '( %s -> %s = %s )' % (A2, TM, SUB))
term = w.s([c1, c2], 'pm2.61dan', '( %s -> %s = %s )' % (Aa, TM, SUB))
s2 = w.s([term], 'sumeq2dv', '( %s -> sum_ a e. %s %s = sum_ a e. %s %s )' % (A0, FP, TM, FP, SUB))
fn = w.s([w.s([], 'fzofi', '%s e. Fin' % FP)], 'a1i', '( %s -> %s e. Fin )' % (A0, FP))
ifc = w.s([w.s([], '1cnd', '( %s -> 1 e. CC )' % Aa), w.s([], '0cnd', '( %s -> 0 e. CC )' % Aa)], 'ifcld', '( %s -> %s e. CC )' % (Aa, IF))
fs = w.s([fn, rc, ifc], 'fsumsub', '( %s -> sum_ a e. %s %s = ( sum_ a e. %s %s - sum_ a e. %s %s ) )' % (A0, FP, SUB, FP, RP('a', 'P'), FP, IF))
# sum of R^a is 0
m1 = w.s([w.s([w.s([w.s([az], 'zcnd', '( %s -> a e. CC )' % Aa)], 'mulridd', '( %s -> ( a x. 1 ) = a )' % Aa)], 'oveq2d', '( %s -> %s = %s )' % (Aa, RP('( a x. 1 )', 'P'), RP('a', 'P')))], 'sumeq2dv', '( %s -> sum_ a e. %s %s = sum_ a e. %s %s )' % (A0, FP, RP('( a x. 1 )', 'P'), FP, RP('a', 'P')))
rs = w.s([pn, w.s([], '1zzd', '( %s -> 1 e. ZZ )' % A0), w.inst('root1sum')], 'syl2anc', '( %s -> sum_ a e. %s %s = if ( P || 1 , P , 0 ) )' % (A0, FP, RP('( a x. 1 )', 'P')))
